claims.quote:
\emph{zero-shot} --- Google's TimesFM-2.0-500M~\cite{Das2024TimesFM},
Amazon's Chronos-2 (120M)~\cite{Ansari2025Chronos2}, and Datadog's
Toto-2.0-2.5B~\cite{Khwaja2026Toto2}

claims.sql:
WITH b AS (SELECT resolution,variate,min(wape) bw FROM provenance.forecast_metrics WHERE span='common' AND candidate='point' AND h=-1 AND model IN ('naive','ewma','holt_winters') GROUP BY 1,2),
     f AS (SELECT resolution,variate,min(wape) fw FROM provenance.forecast_metrics WHERE span='common' AND candidate='point' AND h=-1 AND model IN ('timesfm','chronos','toto') GROUP BY 1,2)
SELECT b.resolution,b.variate,(b.bw-f.fw)/b.bw FROM b JOIN f USING(resolution,variate) ORDER BY 1,2;

claims.quote:
at \SI{1}{\second}
the best model forecasts images at 98.8\% WAPE against 146.1\% for EWMA
and 156.9\% for naive, a one-third relative reduction.

claims.sql:
WITH u AS (SELECT model,resolution,variate,mae FROM provenance.forecast_metrics WHERE span='common' AND candidate='point' AND h=-1 AND mode='uni' AND model IN ('chronos','toto')),
     c AS (SELECT model,resolution,variate,mae FROM provenance.forecast_metrics WHERE span='common' AND candidate='point' AND h=-1 AND mode='cov' AND model IN ('chronos','toto'))
SELECT u.model,u.resolution, avg((c.mae-u.mae)/u.mae)*100 FROM u JOIN c USING(model,resolution,variate) GROUP BY 1,2;

WITH p AS (SELECT model,mode,resolution,variate,wape pw FROM provenance.forecast_metrics WHERE span='common' AND h=-1 AND candidate='point'),
     q AS (SELECT model,mode,resolution,variate,min(wape) qw FROM provenance.forecast_metrics WHERE span='common' AND h=-1 AND candidate<>'point' GROUP BY 1,2,3,4)
SELECT count(*), count(*) FILTER (WHERE qw<pw) FROM p JOIN q USING(model,mode,resolution,variate);

WITH t AS (SELECT variate,wape w FROM provenance.forecast_metrics WHERE span='common' AND candidate='point' AND h=-1 AND resolution='1min' AND model='timesfm'),
     o AS (SELECT variate,min(wape) w FROM provenance.forecast_metrics WHERE span='common' AND candidate='point' AND h=-1 AND resolution='1min' AND model IN ('chronos','toto') GROUP BY 1)
SELECT t.variate,(t.w-o.w)*100 FROM t JOIN o USING(variate);
